val withHandler = baseContext + CoroutineExceptionHandler { _, e -> log(e) }

scope.launch(withHandler) { /* uses IO dispatcher, name, and handler */ }

try {
    fetchData()
} catch (e: CancellationException) {
    throw e // must propagate — never swallow
} catch (e: IOException) {
    handleError(e)
}

try {
    doWork()
} finally {
    withContext(NonCancellable) {
        releaseRemoteLock() // completes even though the coroutine is cancelled
    }
}

val handler = CoroutineExceptionHandler { _, e -> log("Uncaught: $e") }
val scope = CoroutineScope(SupervisorJob() + handler)

scope.launch { throw RuntimeException("boom") } // handler fires — root coroutine
// scope.launch { launch { throw ... } } // also fires — handler applies down the tree

suspend fun processLargeDataset(items: List<Item>) {
    for ((index, item) in items.withIndex()) {
        processItem(item)
        if (index % 1000 == 0) yield() // cooperative cancellation checkpoint
    }
}

val mutex = Mutex()
var counter = 0

suspend fun increment() = mutex.withLock {
    counter++ // safe even with suspend calls elsewhere in the critical section
}

suspend fun loadAndFormat(): String {
    val raw = withContext(Dispatchers.IO) { file.readText() } // sequential switch
    return withContext(Dispatchers.Default) { formatText(raw) } // switches again, sequentially
}

suspend fun computeSum(items: List<Int>): Int {
    var sum = 0
    for (item in items) {
        currentCoroutineContext().ensureActive() // cheap check, no thread yield
        sum += item
    }
    return sum
}

scope.launch { sendAnalyticsEvent() } // no result needed

val deferred = scope.async { fetchUserProfile() }
val profile = deferred.await() // result + exception surface here

suspend fun retryWithDelay() {
    repeat(3) { attempt ->
        try {
            return fetchData()
        } catch (e: IOException) {
            delay(1000L * (attempt + 1)) // thread stays free during the wait
        }
    }
}

class MyViewModel : ViewModel() {
    private val supervisor = SupervisorJob()
    private val scope = CoroutineScope(Dispatchers.Main.immediate + supervisor)

    fun loadEverything() {
        scope.launch { loadProfile() }   // failure here...
        scope.launch { loadStats() }     // ...won't cancel this
    }
}

// ✅ Good — scoped to ViewModel lifecycle
class MyViewModel : ViewModel() {
    fun loadData() {
        viewModelScope.launch {
            val data = repository.fetchData()
            _state.value = data
        }
    }
}

// ❌ Bad — never cancelled, potential leak
GlobalScope.launch {
    repository.fetchData()
}

// Sequential — takes ~2 seconds
val user = fetchUser()       // 1 sec
val posts = fetchPosts()     // 1 sec

// Parallel — takes ~1 second
coroutineScope {
    val user = async { fetchUser() }
    val posts = async { fetchPosts() }
    showProfile(user.await(), posts.await())
}

// Regular Job — one failure cancels everything
val scope = CoroutineScope(Job())

// SupervisorJob — failures are isolated
val scope = CoroutineScope(SupervisorJob())

scope.launch { fetchUser() }    // if this fails...
scope.launch { fetchPosts() }   // ...this keeps running ✅
